public abstract class AbstractSymbolTableModel : AddressBasedTableModel<SymbolRowObject> {

	private static readonly Comparator<SymbolRowObject> NAME_COL_COMPARATOR = (s1, s2) => {
		return s1.toString().compareToIgnoreCase(s2.toString());
	};

	public static readonly int LABEL_COL = 0;
	public static readonly int LOCATION_COL = 1;
	public static readonly int TYPE_COL = 2;
	public static readonly int DATA_TYPE_COL = 3;
