	private class DeleteTask : Task {

		private CompoundCmd<Program> compoundCmd;

		private bool success;
		private string status;

		DeleteTask(CompoundCmd<Program> compoundCmd) : base("Delete Symbols")
    {
			this.compoundCmd = compoundCmd;
		}

		/* @Override */
		public void run(TaskMonitor monitor)
    {

			program.withTransaction(getName(), () => {
				doRun(monitor);
			});
		}

		private void doRun(TaskMonitor monitor)
    {

			monitor.initialize(compoundCmd.size());

			success = true;
			List<Command<Program>> commands = compoundCmd.getCommands();
			foreach (Command<Program> cmd in commands) {

				monitor.increment();

				if (!cmd.applyTo(program)) {
					success = false;
					status = cmd.getStatusMsg();
					break;
				}
			}
		}

		bool success() {
			return success;
		}

		string status() {
			return status;
		}
	}

	private class RenameTask : Task {

		private Symbol symbol;
		private string newName;

		private bool success;
		private string status;

		public RenameTask(Symbol symbol, string newName) : base("Rename Symbol")
    {
			this.symbol = symbol;
			this.newName = newName;
		}

		/* @Override */
		public void run(TaskMonitor monitor)
    {

			program.withTransaction(getName(), () => {
				RenameLabelCmd cmd = new RenameLabelCmd(symbol, newName, SourceType.USER_DEFINED);
				success = cmd.applyTo(program);
			});

		}

		bool success() {
			return success;
		}

		string status() {
			return status;
		}
	}

